BEGIN;
CREATE TABLE IF NOT EXISTS files(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES users, section_id BIGINT REFERENCES sections, submission_id BIGINT REFERENCES submissions, assignment_id BIGINT REFERENCES assignments, announcement_id BIGINT REFERENCES announcements, purpose TEXT NOT NULL CHECK(purpose IN ('avatar','document','material','submission','assignment','announcement')), pathname TEXT NOT NULL UNIQUE, name TEXT NOT NULL, content_type TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes BETWEEN 1 AND 3000000), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS files_owner_idx ON files(owner_id);
CREATE TABLE IF NOT EXISTS resource_completions(material_id BIGINT REFERENCES materials ON DELETE CASCADE, user_id BIGINT REFERENCES users ON DELETE CASCADE, completed_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(material_id,user_id));
CREATE TABLE IF NOT EXISTS assessment_categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id BIGINT NOT NULL REFERENCES sections, name TEXT NOT NULL, weight NUMERIC(6,2) NOT NULL CHECK(weight>0 AND weight<=100), UNIQUE(section_id,name));
ALTER TABLE assessments ADD COLUMN IF NOT EXISTS category_id BIGINT REFERENCES assessment_categories;
ALTER TABLE scores ADD COLUMN IF NOT EXISTS exempt BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS grade_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_id BIGINT NOT NULL REFERENCES assessments, student_id BIGINT NOT NULL REFERENCES users, actor_id BIGINT REFERENCES users, before_value JSONB, after_value JSONB NOT NULL, reason TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS final_grades(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id BIGINT NOT NULL REFERENCES sections, student_id BIGINT NOT NULL REFERENCES users, percentage NUMERIC(5,2) NOT NULL CHECK(percentage BETWEEN 0 AND 100), letter TEXT NOT NULL, gpa NUMERIC(4,2), published BOOLEAN NOT NULL DEFAULT false, finalized_by BIGINT REFERENCES users, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(section_id,student_id));
CREATE TABLE IF NOT EXISTS rubrics(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assignment_id BIGINT NOT NULL REFERENCES assignments, title TEXT NOT NULL, maximum NUMERIC(8,2) NOT NULL CHECK(maximum>0));
CREATE TABLE IF NOT EXISTS rubric_scores(criterion_id BIGINT REFERENCES rubrics ON DELETE CASCADE, submission_id BIGINT REFERENCES submissions, points NUMERIC(8,2) NOT NULL CHECK(points>=0), feedback TEXT NOT NULL DEFAULT '', PRIMARY KEY(criterion_id,submission_id));
CREATE TABLE IF NOT EXISTS schedule_exceptions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id BIGINT REFERENCES sections, title TEXT NOT NULL, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('holiday','cancellation','event','rescheduled')), room_id BIGINT REFERENCES rooms, CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS invitations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('student','teacher')), token_hash TEXT NOT NULL UNIQUE, invited_by BIGINT NOT NULL REFERENCES users, expires_at TIMESTAMPTZ NOT NULL, accepted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS email_jobs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users, subject TEXT NOT NULL, content TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sent','failed')), attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(), sent_at TIMESTAMPTZ, dedupe_key TEXT UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO school_settings(key,value) VALUES('grading','{"bands":[{"minimum":90,"letter":"A","gpa":4},{"minimum":80,"letter":"B","gpa":3},{"minimum":70,"letter":"C","gpa":2},{"minimum":60,"letter":"D","gpa":1},{"minimum":0,"letter":"F","gpa":0}],"late_penalty_percent":0,"late_counts_present":true,"exclude_excused":true}') ON CONFLICT DO NOTHING;
COMMIT;
